{
  "sop_id": "SOP-018",
  "title": "Daily Ops Report",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create report ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Pull production, downtime, and manpower numbers from all sites",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Reconcile numbers against plan",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Calculate KPIs",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Log incidents, deviations, and actions taken",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Compile and publish the report",
      "role": "Executor",
      "type": "work"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "KPI breach or safety event flagged (always required in these cases)"
    },
    {
      "stage": "Lead",
      "condition": "Business validation required (implied when Incharge reviews)"
    },
    {
      "stage": "HOD",
      "condition": "Delegated authority requires it (implied when Incharge reviews)"
    }
  ],
  "dependencies": [],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.95
}
